import sys
from png import load, px
BG=(40,42,54)
path,y = sys.argv[1], int(sys.argv[2])
x0,x1 = int(sys.argv[3]), int(sys.argv[4])
w,h,img=load(path)
prev=None; start=None
def name(c):
    if c is None: return 'bg'
    m={(248,248,242):'FG',(255,255,255):'W',(255,121,198):'PINK',(139,233,253):'CYAN',(102,217,239):'CYAN2',(189,147,249):'PURP',(241,250,140):'YEL',(80,250,123):'GRN',(255,184,108):'ORG',(98,114,164):'CMT'}
    return m.get(c, str(c))
for x in range(x0,x1):
    r,g,b,a=px(img,w,x,y)
    c=(r,g,b) if (a==255 and max(abs(r-BG[0]),abs(g-BG[1]),abs(b-BG[2]))>40) else None
    if c!=prev:
        if prev is not None: print(f"{start}-{x-1} {name(prev)}")
        prev=c; start=x
if prev is not None: print(f"{start}-{x1-1} {name(prev)}")
EOF
